pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // keep the domain wide: only require a strictly positive balance to drain
        // and an actor that is not the owner (owner == this test contract, set at setUp).
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract so there is actually a balance to withdraw
        vm.deal(address(c), amount);
        assertEq(address(c).balance, amount);

        // drive c through withdrawAll as a non-owner
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Universal rule: withdrawAll by a non-owner must never succeed and must
        // never change the contract's balance. The mutant lets any caller drain it.
        assertTrue(!ok && address(c).balance == amount);
    }
}

