pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // Wide admissible domain: any deposit amount, any caller (owner or not).
        vm.assume(amount > 0);
        vm.deal(address(c), amount);

        uint256 balanceBefore = address(c).balance;
        address owner = c.owner();

        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // General rule: only the owner may successfully drain the contract;
        // any other caller must fail and leave the balance unchanged.
        assertTrue(
            actor == owner
                ? (ok && address(c).balance == 0)
                : (!ok && address(c).balance == balanceBefore)
        );
    }
}

