pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        // fund the contract so the withdraw can succeed for any admissible amount
        vm.deal(address(c), amount);
        address owner = address(this); // deployer is owner
        vm.deal(owner, 1);
        uint256 before = address(c).balance;
        vm.prank(owner);
        c.withdraw(amount);
        // General rule: a full withdrawal of `amount` removes exactly `amount` from the contract.
        assertTrue(address(c).balance == before - amount);
    }
}

