pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        // fund the contract with exactly `amount`; owner is address(this) (setUp caller)
        vm.deal(address(c), amount);
        vm.prank(address(this));
        c.withdraw(amount);
        // Reference: full amount transferred out -> contract emptied.
        // Mutant: only amount/2 sent -> balance remains amount/2 > 0.
        assertTrue(address(c).balance == 0, "withdraw must transfer the full amount");
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint amount) external {
        require(address(this).balance >= amount);
        // fund c via its receive() so a withdrawal of 0 is otherwise valid
        (bool funded, ) = address(c).call{value: amount}("");
        require(funded);
        // non-owner attempts to withdraw; in P this must revert
        (bool ok, ) = address(c).call(abi.encodeWithSelector(C.withdraw.selector, uint(0)));
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

